    #[test]
    fn brightness_leaves_text_and_hues_alone() {
        use super::{BRIGHTNESS_LIMIT, brightened};
        for p in [DARK, LIGHT] {
            for step in -BRIGHTNESS_LIMIT..=BRIGHTNESS_LIMIT {
                let q = brightened(&p, step);
                let kept = |p: &Palette| {
                    (
                        [
                            p.text,
                            p.text_secondary,
                            p.text_tertiary,
                            p.text_disabled,
                            p.accent,
                            p.accent_fill,
                            p.success,
                            p.warning,
                            p.error,
                            p.purple,
                            p.cyan,
                            p.orange,
                        ],
                        [p.dim, p.bevel_light, p.bevel_shade],
